from typing import Callable, Any, Optional


class QueueWorker:
    SENTINEL = object()

    def __init__(
        self, 
        callback: Callable[[Any], None], 
        queue_obj: queue.Queue, 
        daemon: bool = True,
        error_callback: Optional[Callable[[Exception, Any], None]] = None
    ):
        self.callback = callback
        self.queue = queue_obj
        self.daemon = daemon
        self.error_callback = error_callback
        self.thread: Optional[threading.Thread] = None
        self.running = False

    def start(self) -> None:
        """Start the worker thread."""
        if self.thread is not None:
            raise RuntimeError("Worker already started")
        self.running = True
        self.thread = threading.Thread(target=self._run, daemon=self.daemon)
        self.thread.start()

    def _run(self) -> None:
        """Main worker loop."""
        while self.running:
            try:
                item = self.queue.get(timeout=0.5)
                if item is self.SENTINEL:
                    break
                try:
                    self.callback(item)
                except Exception as e:
                    if self.error_callback:
                        self.error_callback(e, item)
                    else:
                        print(f"Error processing item {item}: {e}")
                finally:
                    self.queue.task_done()
            except queue.Empty:
                continue

    def stop(self) -> None:
        """Stop the worker thread gracefully via sentinel value."""
        self.running = False
        self.queue.put(self.SENTINEL)
        if self.thread:
            self.thread.join()

    def is_alive(self) -> bool:
        """Check if worker thread is running."""
        return self.thread is not None and self.thread.is_alive()


if __name__ == "__main__":
    q = queue.Queue()

    def process_item(item):
        if item == "item_2":
            raise ValueError("Simulated error")
        print(f"Processing: {item}")

    def handle_error(exc, item):
        print(f"Failed to process {item}: {exc}")

    worker = QueueWorker(callback=process_item, queue_obj=q, error_callback=handle_error)
    worker.start()

    for i in range(5):
        q.put(f"item_{i}")

    import time
    time.sleep(1)
    worker.stop()
